package com.greatleyposhley.professy.collaboration;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.Scheduled;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.io.*;
import java.util.zip.*;
import static com.greatleyposhley.professy.collaboration.WorkAccess.number;
import static com.greatleyposhley.professy.collaboration.DeliveryRules.*;

/** Worker credentials are limited to a single agent's queued work, never human access tokens. */
@RestController @RequestMapping("/api/delivery-worker/{agentId}")
public class DeliveryWorker {
 final DeliveryOperations ops;final WorkAccess access;final tools.jackson.databind.ObjectMapper json;final Path storage;
 public DeliveryWorker(DeliveryOperations ops,WorkAccess access,tools.jackson.databind.ObjectMapper json,@org.springframework.beans.factory.annotation.Value("${app.attachments.directory:./.runtime/attachments}")String directory){this.ops=ops;this.access=access;this.json=json;this.storage=Path.of(directory).toAbsolutePath().normalize();}
 Map<String,Object> identity(long agentId,String credential){
  if(credential==null||credential.length()<48||credential.length()>200)throw denied();
  var rows=access.jdbc.queryForList("SELECT c.*,a.display_name AS agentName,a.status,p.instructions AS agentInstructions FROM delivery_agent_config c JOIN workspace_actors a ON a.id=c.agent_id AND a.org_id=c.org_id JOIN workspace_agent_profiles p ON p.actor_id=a.id WHERE c.agent_id=? FOR UPDATE",agentId);
  if(rows.isEmpty())throw denied();var c=rows.getFirst();if(!MessageDigest.isEqual(DeliveryOperations.hash(credential).getBytes(StandardCharsets.UTF_8),Objects.toString(c.get("worker_hash"),"").getBytes(StandardCharsets.UTF_8))||!Boolean.TRUE.equals(c.get("enabled"))||!"ACTIVE".equals(c.get("status")))throw denied();
  var grants=new HashSet<String>();for(var row:access.jdbc.queryForList("SELECT r.permissions_json FROM agent_workspace_roles a JOIN workspace_roles r ON r.code=a.role_code AND r.org_id=? WHERE a.actor_id=?",c.get("org_id"),agentId))for(Object p:json.readValue(row.get("permissions_json").toString(),List.class))grants.add(p.toString());
  var overrides=new HashMap<String,Boolean>();for(var r:access.jdbc.queryForList("SELECT permission,allowed FROM agent_permission_overrides WHERE actor_id=?",agentId))overrides.put(r.get("permission").toString(),Boolean.TRUE.equals(r.get("allowed"))||number(r.get("allowed"))==1);
  for(String permission:List.of("TICKETS.READ","TICKETS.UPDATE"))if(!WorkspacePolicy.resolve(permission,grants,overrides))throw denied();
  access.jdbc.update("UPDATE delivery_agent_config SET last_seen=CURRENT_TIMESTAMP(6) WHERE agent_id=?",agentId);return c;
 }
 static String leaseToken(){byte[] bytes=new byte[32];new java.security.SecureRandom().nextBytes(bytes);return HexFormat.of().formatHex(bytes);}
 private ResponseStatusException denied(){return new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Worker enrollment is unavailable or revoked");}
 void currentAssignment(Map<String,Object> job){access.executionRequester(number(job.get("requested_by")));if(access.jdbc.queryForList("SELECT a.actor_id FROM ticket_actor_assignments a JOIN workspace_agent_projects p ON p.actor_id=a.actor_id AND p.project_id=a.project_id JOIN user_account u ON u.id=? AND u.org_id=a.org_id AND u.is_active=1 WHERE a.org_id=? AND a.actor_id=? AND a.ticket_type=? AND a.ticket_id=? AND a.assignment_role='ASSIGNEE' FOR UPDATE",job.get("requested_by"),job.get("org_id"),job.get("agent_id"),job.get("ticket_kind"),job.get("ticket_id")).size()!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Ticket was reassigned or project access was removed");}
 @PostMapping("/claim") @Transactional public Object claim(@PathVariable long agentId,@RequestHeader(value="X-Worker-Key",required=false)String key,@RequestBody Map<String,Object>b){var c=identity(agentId,key);String worker=required(b.get("workerId"),100);report(agentId,c,b);if(access.jdbc.queryForObject("SELECT COUNT(*) FROM delivery_jobs WHERE agent_id=? AND state='RUNNING'",Integer.class,agentId)>0)return Map.of("idle",true);var rows=access.jdbc.queryForList("SELECT * FROM delivery_jobs WHERE agent_id=? AND org_id=? AND state='QUEUED' ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED",agentId,c.get("org_id"));if(rows.isEmpty())return Map.of("idle",true);var job=rows.getFirst();currentAssignment(job);var contexts=access.jdbc.queryForList("SELECT context_json FROM ticket_execution_context WHERE job_id=?",job.get("id"));Map<String,Object> context=contexts.isEmpty()?Map.of():json.readValue(contexts.getFirst().get("context_json").toString(),Map.class);List<String> required="repository".equals(job.get("workflow"))?RuntimeSkills.required(context.get("requiredSkills"),Objects.toString(context.get("testProfile"),"PYTHON_UNITTEST")):List.of("python-stdlib","unittest");var readiness=RuntimeSkills.readiness(c,RuntimeSkills.report(access.jdbc,json,number(c.get("org_id")),agentId),required,json);if(!Boolean.TRUE.equals(readiness.get("ready"))){finish(job,"FAILED",Map.of("message",String.join("; ",(List<String>)readiness.get("reasons")),"actorType","AGENT"));return Map.of("idle",true,"blockedJob",job.get("id"));}String lease=leaseToken();access.jdbc.update("UPDATE delivery_jobs SET state='RUNNING',worker_id=?,lease_token=?,lease_until=CURRENT_TIMESTAMP(6)+INTERVAL 15 MINUTE,updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",worker,lease,job.get("id"));access.jdbc.update("UPDATE delivery_support SET state='RUNNING',updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",job.get("support_id"));ticketStatus(job,"IN_PROGRESS");job.remove("result_json");var execution=access.jdbc.queryForList("SELECT context_json FROM ticket_execution_context WHERE job_id=?",job.get("id"));if(!execution.isEmpty())job.put("execution",json.readValue(execution.getFirst().get("context_json").toString(),Map.class));job.put("lease",lease);job.put("model",c.get("model"));job.put("agentName",c.get("agentName"));job.put("agentInstructions",c.get("agentInstructions"));job.put("reviewRequired",true);return job;}
 Map<String,Object> job(long agentId,String id,String lease,Map<String,Object> identity){var rows=access.jdbc.queryForList("SELECT * FROM delivery_jobs WHERE id=? AND agent_id=? AND org_id=? FOR UPDATE",id,agentId,identity.get("org_id"));if(rows.isEmpty())throw denied();var j=rows.getFirst();if(lease==null||!MessageDigest.isEqual(Objects.toString(j.get("lease_token"),"").getBytes(StandardCharsets.UTF_8),lease.getBytes(StandardCharsets.UTF_8)))throw denied();if(j.get("lease_until") instanceof java.sql.Timestamp until&&until.toInstant().isBefore(java.time.Instant.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Worker lease expired");return j;}
 @PostMapping("/jobs/{id}/heartbeat") @Transactional public Object heartbeat(@PathVariable long agentId,@PathVariable String id,@RequestHeader(value="X-Worker-Key",required=false)String key,@RequestBody Map<String,Object>b){var c=identity(agentId,key);var j=job(agentId,id,text(b.get("lease"),100),c);currentAssignment(j);if(!"RUNNING".equals(j.get("state")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Run is no longer active");access.jdbc.update("UPDATE delivery_jobs SET lease_until=CURRENT_TIMESTAMP(6)+INTERVAL 15 MINUTE,updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",id);appendEvents(j,b.get("events"));report(agentId,c,b);return Map.of("active",true,"eventCursor",eventCursor(id));}
 @PostMapping("/jobs/{id}/complete") @Transactional public Object complete(@PathVariable long agentId,@PathVariable String id,@RequestHeader(value="X-Worker-Key",required=false)String key,@RequestBody Map<String,Object>b)throws Exception{
  var c=identity(agentId,key);var j=job(agentId,id,text(b.get("lease"),100),c);if(Set.of("REVIEW_READY","CHECKS_FAILED","APPROVED","FAILED").contains(j.get("state")))return Map.of("state",j.get("state"));if(!"RUNNING".equals(j.get("state")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Run is no longer active");currentAssignment(j);appendEvents(j,b.get("events"));
  String failure=text(b.get("error"),2000);if(!failure.isEmpty()){finish(j,"FAILED",Map.of("message",failure,"agentName",c.get("agentName"),"actorType","AGENT","logs",text(b.get("logs"),60000),"runtimeRunId",text(b.get("runtimeRunId"),32)));return Map.of("state","FAILED");}
  boolean repository="repository".equals(j.get("workflow"));var files=repository?repositoryFiles(b.get("files")):DeliveryRules.files(b.get("files"));boolean passed=Boolean.TRUE.equals(b.get("checksPassed"));if("priority-normalizer-v1".equals(j.get("workflow")))passed=passed&&Boolean.TRUE.equals(b.get("acceptancePassed"));String summary=required(b.get("summary"),8000);var result=new LinkedHashMap<String,Object>();result.put("summary",summary);result.put("agentName",c.get("agentName"));result.put("actorType","AGENT");result.put("checksPassed",passed);result.put("acceptancePassed",Boolean.TRUE.equals(b.get("acceptancePassed")));result.put("logs",text(b.get("logs"),60000));result.put("runtimeRunId",text(b.get("runtimeRunId"),32));result.put("requiresHumanReview",true);result.put("productionChanges",false);result.put("repositoryChanges",repository);if(repository){result.put("pullRequest",b.get("pullRequest"));result.put("baseline",b.get("baseline"));result.put("regression",b.get("regression"));result.put("diff",text(b.get("diff"),60000));}result.put("model",c.get("model"));result.put("files",files.keySet());result.put("serviceId",j.get("service_id"));
  var bytes=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(bytes,StandardCharsets.UTF_8)){for(var f:files.entrySet())entry(zip,f.getKey(),f.getValue());entry(zip,"run-evidence.json",json.writeValueAsString(result));String graphJson="{\"nodes\":[],\"edges\":[]}";List<Map<String,Object>> catalog=List.of();
   if(repository){var context=access.jdbc.queryForList("SELECT context_json FROM ticket_execution_context WHERE job_id=?",id);if(!context.isEmpty()){var spec=json.readValue(context.getFirst().get("context_json").toString(),Map.class);if(spec.get("infrastructure") instanceof Map<?,?> infra&&infra.get("graph")!=null)graphJson=json.writeValueAsString(infra.get("graph"));if(spec.get("resourceCatalog") instanceof List<?> resources)catalog=(List<Map<String,Object>>)(List<?>)resources;}}
   else{var graph=access.jdbc.queryForList("SELECT graph_json FROM delivery_architectures WHERE org_id=? AND project_id=?",j.get("org_id"),j.get("project_id"));if(!graph.isEmpty())graphJson=graph.getFirst().get("graph_json").toString();catalog=access.jdbc.queryForList("SELECT id,name,description,kind,environment,port FROM delivery_services WHERE org_id=? AND project_id=? ORDER BY name",j.get("org_id"),j.get("project_id"));}
   entry(zip,"architecture.json",graphJson);entry(zip,"service-catalog.json",json.writeValueAsString(catalog));entry(zip,"architecture.svg",architectureSvg(json.readValue(graphJson,Map.class),catalog));entry(zip,"REVIEW.md","# Local agent delivery\n\nAgent: "+c.get("agentName")+"\nRun: "+id+"\nChecks passed: "+passed+"\n\n"+summary+"\n\nReview the pull request, changed source and original/regression check output before merging. Passing generated tests does not establish production acceptance. This artifact is not a deployment.\n");}
  String name=j.get("org_id")+"/"+UUID.randomUUID();Path target=storage.resolve(name).normalize();Files.createDirectories(target.getParent());Files.write(target,bytes.toByteArray(),StandardOpenOption.CREATE_NEW);long attachment=ops.insert("INSERT INTO ticket_attachments(org_id,project_id,ticket_type,ticket_id,uploaded_by,original_name,storage_name,content_type,byte_size) VALUES(?,?,?,?,?,?,?,?,?)",j.get("org_id"),j.get("project_id"),j.get("ticket_kind"),j.get("ticket_id"),j.get("requested_by"),"agent-delivery-"+id.substring(0,8)+".zip",name,"application/zip",bytes.size());access.jdbc.update("INSERT INTO delivery_evidence(attachment_id,job_id,agent_id,org_id) VALUES(?,?,?,?)",attachment,id,agentId,j.get("org_id"));access.jdbc.update("UPDATE delivery_jobs SET attachment_id=? WHERE id=?",attachment,id);result.put("attachmentId",attachment);finish(j,passed?"REVIEW_READY":"CHECKS_FAILED",result);return Map.of("state",passed?"REVIEW_READY":"CHECKS_FAILED","attachmentId",attachment);
 }
 void report(long agentId,Map<String,Object> c,Map<String,Object> body){if(body.get("capabilities") instanceof Map<?,?> raw){var report=RuntimeSkills.validateReport(raw);access.jdbc.update("INSERT INTO delivery_worker_reports(agent_id,org_id,worker_id,report_json) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE worker_id=VALUES(worker_id),report_json=VALUES(report_json),reported_at=CURRENT_TIMESTAMP(6)",agentId,c.get("org_id"),required(body.getOrDefault("workerId","local-"+agentId),100),json.writeValueAsString(report));}}
 void appendEvents(Map<String,Object> job,Object raw){for(var event:RuntimeSkills.events(raw))access.jdbc.update("INSERT IGNORE INTO delivery_job_events(org_id,job_id,worker_sequence,event,message,occurred_at) VALUES(?,?,?,?,?,?)",job.get("org_id"),job.get("id"),event.get("sequence"),event.get("event"),event.get("message"),event.get("occurredAt"));}
 long eventCursor(String id){return Optional.ofNullable(access.jdbc.queryForObject("SELECT MAX(worker_sequence) FROM delivery_job_events WHERE job_id=? AND worker_sequence>0",Long.class,id)).orElse(0L);}
 void ticketStatus(Map<String,Object> j,String state){String table=switch(j.get("ticket_kind").toString()){case "EPIC"->"epics";case "STORY"->"stories";case "TASK"->"tasks";case "ISSUE"->"issues";default->throw new IllegalArgumentException("Unsupported ticket kind");};access.jdbc.update("UPDATE "+table+" SET status=? WHERE id=? AND org_id=?",state,j.get("ticket_id"),j.get("org_id"));}
 static Map<String,String> repositoryFiles(Object value){if(!(value instanceof List<?> list)||list.isEmpty()||list.size()>25)throw new IllegalArgumentException("Invalid evidence files");var result=new LinkedHashMap<String,String>();int total=0;for(var item:list){if(!(item instanceof Map<?,?> entry))throw new IllegalArgumentException("Invalid file");String name=TicketExecution.safePath(entry.get("path")),body=Objects.toString(entry.get("content"),"");if(body.length()>120000)throw new IllegalArgumentException("Evidence file exceeds limit");if(result.put(name,body)!=null)throw new IllegalArgumentException("Duplicate file");total+=body.length();}if(total>500000)throw new IllegalArgumentException("Evidence exceeds limit");return result;}
 @PostMapping("/jobs/{id}/context") @Transactional public Object context(@PathVariable long agentId,@PathVariable String id,@RequestHeader(value="X-Worker-Key",required=false)String key,@RequestBody Map<String,Object>b){var c=identity(agentId,key);var j=job(agentId,id,text(b.get("lease"),100),c);currentAssignment(j);if(!"RUNNING".equals(j.get("state")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Run is no longer active");var rows=access.jdbc.queryForList("SELECT context_json FROM ticket_execution_context WHERE job_id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Repository execution context not found");var user=access.jdbc.queryForMap("SELECT org_role FROM user_account WHERE id=? AND org_id=?",j.get("requested_by"),j.get("org_id"));return Map.of("orgId",j.get("org_id"),"userId",j.get("requested_by"),"isAdmin","SUPER_USER".equals(user.get("org_role")),"agentId",agentId,"agentName",c.get("agentName"),"ticketKind",j.get("ticket_kind"),"ticketId",j.get("ticket_id"),"execution",json.readValue(rows.getFirst().get("context_json").toString(),Map.class));}
 static String xml(Object value){return Objects.toString(value,"").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
 static String architectureSvg(Map<String,Object> graph,List<Map<String,Object>> catalog){
  var names=new HashMap<String,String>();for(var service:catalog)names.put(service.get("id").toString(),xml(service.get("name")));var positions=new HashMap<String,Map<?,?>>();for(Object item:(List<?>)graph.get("nodes")){var n=(Map<?,?>)item;positions.put(n.get("id").toString(),n);}double height=700;for(var n:positions.values())height=Math.max(height,((Number)n.get("y")).doubleValue()+140);
  var svg=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1350 "+height+"\"><title>Project architecture snapshot</title><rect width=\"100%\" height=\"100%\" fill=\"white\"/>");
  for(Object item:(List<?>)graph.get("edges")){var e=(Map<?,?>)item;var a=positions.get(e.get("from").toString());var b=positions.get(e.get("to").toString());if(a==null||b==null)continue;double x1=((Number)a.get("x")).doubleValue()+125,y1=((Number)a.get("y")).doubleValue()+75,x2=((Number)b.get("x")).doubleValue()+125,y2=((Number)b.get("y")).doubleValue();svg.append("<path d=\"M").append(x1).append(",").append(y1).append(" L").append(x2).append(",").append(y2).append("\" stroke=\"#879ab6\" stroke-width=\"2\"/>");}
  for(var entry:positions.entrySet()){var n=entry.getValue();svg.append("<g transform=\"translate(").append(((Number)n.get("x")).doubleValue()).append(",").append(((Number)n.get("y")).doubleValue()).append(")\"><rect width=\"250\" height=\"75\" rx=\"10\" fill=\"#edf3ff\" stroke=\"#c7d4e6\"/><text x=\"14\" y=\"40\" font-family=\"system-ui\" font-size=\"14\" fill=\"#1d3456\">").append(names.getOrDefault(entry.getKey(),"Service")).append("</text></g>");}
  return svg.append("</svg>").toString();
 }
 private void entry(ZipOutputStream zip,String name,String body)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(body.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
 void finish(Map<String,Object> j,String state,Map<String,Object> result){access.jdbc.update("INSERT IGNORE INTO delivery_job_events(org_id,job_id,worker_sequence,event,message,occurred_at) VALUES(?,?,-2,?,?,?)",j.get("org_id"),j.get("id"),state,Objects.toString(result.get("message"),Objects.toString(result.get("summary"),state)),java.time.Instant.now().toString());if("REVIEW_READY".equals(state))ticketStatus(j,"IN_REVIEW");access.jdbc.update("UPDATE delivery_jobs SET state=?,result_json=?,lease_until=NULL,updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",state,json.writeValueAsString(result),j.get("id"));access.jdbc.update("UPDATE delivery_support SET state=?,updated_at=CURRENT_TIMESTAMP(6) WHERE id=?","CHECKS_FAILED".equals(state)?"FAILED":state,j.get("support_id"));var before=Map.of("title",j.get("title"));var after=new LinkedHashMap<String,Object>(result);after.put("title",j.get("title"));after.put("runId",j.get("id"));access.jdbc.update("CALL workspace_record_ticket_change(?,?,?,?,?,?,?,?)",j.get("org_id"),j.get("project_id"),j.get("ticket_kind"),j.get("ticket_id"),0,"AGENT_"+state,json.writeValueAsString(before),json.writeValueAsString(after));}
 @Scheduled(fixedDelay=30000) @Transactional public void expired(){var rows=access.jdbc.queryForList("SELECT * FROM delivery_jobs WHERE state='RUNNING' AND lease_until<CURRENT_TIMESTAMP(6) LIMIT 25 FOR UPDATE SKIP LOCKED");for(var j:rows)finish(j,"FAILED",Map.of("message","Worker lease expired. Retry explicitly; no automatic duplicate execution.","actorType","SYSTEM"));}
}
